cd codeanalyzer/src/main/java/nl/obren/sokrates/sourcecode && python3 - <<'EOF'
import re
p='aspects/SourceCodeAspectUtils.java'
s=open(p).read()
old='''    @JsonIgnore
    public static List<NamedSourceCodeAspect> getAspectsPerExtensions('''
new='''    // Naming of the per-extension entries (linesOfCodePerExtension, fileCountPerExtension in analysisResults.json,
    // and the per-extension aspects below). Today an entry is named with a decorated label, "  *.java".
    public static String perExtensionName(String extension) {
        return decoratedExtensionLabel(extension);
    }

    // The decorated "  *.java" label (also used by the indented lines of the textual analysis summary).
    public static String decoratedExtensionLabel(String extension) {
        return "  *." + extension;
    }

    // The plain lower-cased extension of a per-extension entry name ("  *.java" -> "java"),
    // used e.g. for the per-extension metric ids (LINES_OF_CODE_MAIN_EXT_JAVA, NUMBER_OF_FILES_MAIN_EXT_JAVA).
    public static String extensionName(String perExtensionName) {
        return perExtensionName == null ? "" : perExtensionName.replace("*.", "").trim().toLowerCase();
    }

    // The key under which a landscape merges/aggregates per-extension lines-of-code entries of its repositories
    // (main scope and the merged "other" category). Entries with the same key are merged into one entry.
    public static String landscapeAggregationKey(String perExtensionName) {
        return perExtensionName.toLowerCase();
    }

    // One aspect per (lower-cased) file extension, named by perExtensionName(extension), sorted by LOC desc.
    @JsonIgnore
    public static List<NamedSourceCodeAspect> getAspectsPerExtensions('''
assert old in s; s=s.replace(old,new)
old='new NamedSourceCodeAspect("  *." + extension)'
assert old in s; s=s.replace(old,'new NamedSourceCodeAspect(perExtensionName(extension))')
open(p,'w').write(s)

p='analysis/AnalysisUtils.java'
s=open(p).read()
old='''            String extensionMetricName = name + "_EXT_" + aspectPerExtension.getName().replace("*.", "");'''
new='''            String extension = SourceCodeAspectUtils.extensionName(aspectPerExtension.getName());
            String extensionMetricName = name + "_EXT_" + extension;'''
assert old in s; s=s.replace(old,new)
old='''detailedInfo(textSummary, progressFeedback, aspectPerExtension.getName() + ": "'''
new='''detailedInfo(textSummary, progressFeedback, SourceCodeAspectUtils.decoratedExtensionLabel(extension) + ": "'''
assert old in s; s=s.replace(old,new)
open(p,'w').write(s)

p='landscape/analysis/LandscapeAnalysisResults.java'
s=open(p).read()
old='String id = metric.getName().toLowerCase();'
assert old in s; s=s.replace(old,'String id = SourceCodeAspectUtils.landscapeAggregationKey(metric.getName());')
old='''            list.forEach(metric -> {
                if (mergedMap.containsKey(metric.getName())) {
                    mergedMap.get(metric.getName()).setValue(mergedMap.get(metric.getName()).getValue().doubleValue() + metric.getValue().doubleValue());
                } else {
                    NumericMetric newMetric = new NumericMetric(metric.getName(), metric.getValue());'''
new='''            list.forEach(metric -> {
                String name = SourceCodeAspectUtils.landscapeAggregationKey(metric.getName());
                if (mergedMap.containsKey(name)) {
                    mergedMap.get(name).setValue(mergedMap.get(name).getValue().doubleValue() + metric.getValue().doubleValue());
                } else {
                    NumericMetric newMetric = new NumericMetric(name, metric.getValue());'''
assert old in s; s=s.replace(old,new)
s=s.replace('import nl.obren.sokrates.sourcecode.analysis.results.HistoryPerExtension;\n','import nl.obren.sokrates.sourcecode.analysis.results.HistoryPerExtension;\nimport nl.obren.sokrates.sourcecode.aspects.SourceCodeAspectUtils;\n',1)
